-- Games get their own table, and every game_slug / game column becomes game_id.
-- Generated by drizzle-kit, then HAND-EDITED to carry the data over (its rebuild
-- would have copied a game_id column that did not exist yet). See
-- docs/standards/database.md.
--
-- D1 runs a migration as one transaction with foreign keys enforced, and ignores
-- PRAGMA foreign_keys there, so nothing below relies on turning them off:
-- - child rows are set aside in a __keep_ table before their parent table is
--   dropped, because DROP TABLE deletes every row first, and that would cascade
--   (online_match_player) or orphan (coupon_redemption) them;
-- - defer_foreign_keys only moves the remaining checks to the commit.
-- Every game_id is filled through a LEFT JOIN on game.slug, so a slug the seed
-- missed fails the NOT NULL loudly instead of dropping the row.
PRAGMA defer_foreign_keys = on;--> statement-breakpoint
CREATE TABLE `game` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`slug` text NOT NULL,
	`created_at` integer DEFAULT (unixepoch() * 1000) NOT NULL
);
--> statement-breakpoint
CREATE UNIQUE INDEX `game_slug_unique` ON `game` (`slug`);--> statement-breakpoint
-- Every slug in use (archived games and "<slug>:<mode>" online boards included),
-- plus the catalogue as of this migration. A later game gets its row from gameIdOf.
-- One INSERT per source: D1 caps a compound SELECT at 5 terms, so no big UNION here.
INSERT OR IGNORE INTO `game` (`slug`) VALUES
	('caro'), ('co-ca-ngua'), ('co-lat'), ('co-ty-phu'), ('co-vua'), ('dao-vang'),
	('khu-cach-ly'), ('ky-tuc-xa'), ('meo-vu-tru'), ('noi-thu'), ('o-an-quan'),
	('phi-doi'), ('rot-nuoc'), ('tiem-banh-may'), ('xep-tang'), ('xu-vu-tru');--> statement-breakpoint
INSERT OR IGNORE INTO `game` (`slug`) SELECT DISTINCT `game_slug` FROM `score` ORDER BY 1;--> statement-breakpoint
INSERT OR IGNORE INTO `game` (`slug`) SELECT DISTINCT `game_slug` FROM `game_save` ORDER BY 1;--> statement-breakpoint
INSERT OR IGNORE INTO `game` (`slug`) SELECT DISTINCT `game_slug` FROM `game_stat` ORDER BY 1;--> statement-breakpoint
INSERT OR IGNORE INTO `game` (`slug`) SELECT DISTINCT `game_slug` FROM `online_match` ORDER BY 1;--> statement-breakpoint
INSERT OR IGNORE INTO `game` (`slug`) SELECT DISTINCT `game_slug` FROM `favorite` ORDER BY 1;--> statement-breakpoint
INSERT OR IGNORE INTO `game` (`slug`) SELECT DISTINCT `game` FROM `coupon` WHERE `game` IS NOT NULL ORDER BY 1;--> statement-breakpoint
INSERT OR IGNORE INTO `game` (`slug`) SELECT DISTINCT `game` FROM `coupon_redemption` ORDER BY 1;--> statement-breakpoint
CREATE TABLE `__new_score` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`game_id` integer NOT NULL,
	`user_id` text,
	`name` text NOT NULL,
	`score` integer NOT NULL,
	`detail` text,
	`created_at` integer DEFAULT (unixepoch()) NOT NULL,
	FOREIGN KEY (`game_id`) REFERENCES `game`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`user_id`) REFERENCES `user`(`id`) ON UPDATE no action ON DELETE cascade
);
--> statement-breakpoint
INSERT INTO `__new_score`("id", "game_id", "user_id", "name", "score", "detail", "created_at")
SELECT s."id", g."id", s."user_id", s."name", s."score", s."detail", s."created_at"
FROM `score` s LEFT JOIN `game` g ON g."slug" = s."game_slug";--> statement-breakpoint
