-- online_match is the parent of online_match_player (ON DELETE cascade): set the
-- players aside, drop both, and put the players back unchanged.
CREATE TABLE `__new_online_match` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`game_id` integer NOT NULL,
	`mode` text NOT NULL,
	`room_code` text NOT NULL,
	`settings` text DEFAULT '{}' NOT NULL,
	`posted_at` integer NOT NULL,
	`played_at` integer DEFAULT (unixepoch()) NOT NULL,
	FOREIGN KEY (`game_id`) REFERENCES `game`(`id`) ON UPDATE no action ON DELETE no action
);
--> statement-breakpoint
INSERT INTO `__new_online_match`("id", "game_id", "mode", "room_code", "settings", "posted_at", "played_at")
SELECT m."id", g."id", m."mode", m."room_code", m."settings", m."posted_at", m."played_at"
FROM `online_match` m LEFT JOIN `game` g ON g."slug" = m."game_slug";--> statement-breakpoint
CREATE TABLE `__keep_online_match_player` AS SELECT * FROM `online_match_player`;--> statement-breakpoint
DROP TABLE `online_match_player`;--> statement-breakpoint
