-- coupon is the parent of coupon_redemption: same dance, the redemptions get
-- their game_id on the way out.
CREATE TABLE `__new_coupon` (
	`code` text PRIMARY KEY NOT NULL,
	`game_id` integer,
	`rewards` text NOT NULL,
	`max_uses` integer DEFAULT 1 NOT NULL,
	`uses` integer DEFAULT 0 NOT NULL,
	`expires_at` integer,
	`disabled` integer DEFAULT false NOT NULL,
	`note` text,
	`created_at` integer DEFAULT (unixepoch() * 1000) NOT NULL,
	FOREIGN KEY (`game_id`) REFERENCES `game`(`id`) ON UPDATE no action ON DELETE no action,
	CONSTRAINT "coupon_code_shape" CHECK(code = upper(code) and instr(code, ' ') = 0 and instr(code, '-') = 0),
	CONSTRAINT "coupon_rewards_array" CHECK(json_valid(rewards) and json_type(rewards) = 'array')
);
--> statement-breakpoint
INSERT INTO `__new_coupon`("code", "game_id", "rewards", "max_uses", "uses", "expires_at", "disabled", "note", "created_at")
